# Объединяем дополнительные персонажи
for category, personas in additional_personas.items():
    if category in personas_data:
        personas_data[category].extend(personas)

def main():
    print('=' * 60)
    print('Создание 100 новых персонажей по категориям')
    print('=' * 60)
    
    # Удаляем всех старых системных персонажей
    old_personas = Persona.objects.filter(user=None)
    count = old_personas.count()
    print(f'\nУдаление старых персонажей: {count}...')
    old_personas.delete()
    print(f'[OK] Удалено старых персонажей: {count}')
    
    # Создаем новых персонажей
    total_created = 0
    total_updated = 0
    
    for category, personas in personas_data.items():
        print(f'\nКатегория: {category} ({len(personas)} персонажей)')
        for persona_data in personas:
            persona, created = Persona.objects.get_or_create(
                name=persona_data['name'],
                user=None,
                defaults={
                    'style_description': persona_data['style'],
                    'description': persona_data.get('desc', '')
                }
            )
            if created:
                total_created += 1
                try:
                    print(f'  [+] {persona.name}')
                except:
                    print(f'  [+] Создан персонаж')
            else:
                persona.style_description = persona_data['style']
                persona.description = persona_data.get('desc', '')
                persona.save()
                total_updated += 1
                try:
                    print(f'  [~] {persona.name}')
                except:
                    print(f'  [~] Обновлен персонаж')
    
    print(f'\n{"=" * 60}')
    print(f'Готово! Создано: {total_created}, обновлено: {total_updated}')
    print(f'Всего персонажей: {Persona.objects.filter(user=None).count()}')
    print(f'{"=" * 60}')

if __name__ == '__main__':
    main()

